#[derive(Clone)]
pub struct JstfModList<'a> {
    data: FontData<'a>,
}

#[allow(clippy::needless_lifetimes)]
impl<'a> JstfModList<'a> {
    pub const MIN_SIZE: usize = u16::RAW_BYTE_LEN;
    basic_table_impls!(impl_the_methods);

    pub fn lookup_count(&self) -> u16 {
        let range = self.lookup_count_byte_range();
        self.data.read_at(range.start).ok().unwrap_or_default()
    }

    pub fn lookup_indices(&self) -> &'a [BigEndian<u16>] {
        let range = self.lookup_indices_byte_range();
        self.data.read_array(range).ok().unwrap_or_default()
    }

    pub fn lookup_count_byte_range(&self) -> Range<usize> {
        let start = 0;
        let end = start + u16::RAW_BYTE_LEN;
        start..end
    }

    pub fn lookup_indices_byte_range(&self) -> Range<usize> {
        let lookup_count = self.lookup_count();
        let start = self.lookup_count_byte_range().end;
        let end = start + (transforms::to_usize(lookup_count)).saturating_mul(u16::RAW_BYTE_LEN);
        start..end
    }
}

const _: () = assert!(FontData::default_data_long_enough(JstfModList::MIN_SIZE));

impl Default for JstfModList<'_> {
    fn default() -> Self {
        Self {
            data: FontData::default_table_data(),
        }
    }
}
